import{_ as e,o,c as i,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_3.md"}'),s={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_3.md"};function t(r,a,l,c,d,u){return o(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-analisis-sistematizacion-y-socializacion" tabindex="-1">Eje Temático: Análisis, Sistematización y Socialización <a class="header-anchor" href="#eje-tematico-analisis-sistematizacion-y-socializacion" aria-label="Permalink to &quot;Eje Temático: Análisis, Sistematización y Socialización&quot;">​</a></h3><hr><h2 id="🧭-introduccion-dar-sentido-al-caos" tabindex="-1">🧭 Introducción: Dar Sentido al Caos <a class="header-anchor" href="#🧭-introduccion-dar-sentido-al-caos" aria-label="Permalink to &quot;🧭 Introducción: Dar Sentido al Caos&quot;">​</a></h2><p>Imagina que fuiste a la comunidad y aplicaste 50 encuestas, hiciste 3 entrevistas y llenaste 4 hojas de observación sobre el estado de los equipos. Tienes en tus manos una montaña de papeles y datos sueltos. Por sí solos, esos datos no significan nada; son ruido.</p><p>La <strong>Sistematización y el Análisis</strong> es el proceso intelectual mediante el cual tomas todo ese caos, lo ordenas y lo conviertes en <strong>Información útil</strong>. Descubres que, aunque la gente pidió una red nueva, tus datos muestran que el 80% de los equipos ni siquiera encienden. Es aquí donde la realidad de la comunidad se cruza con tu criterio técnico.</p><hr><h2 id="🏛️-capitulo-i-organizacion-de-la-informacion" tabindex="-1">🏛️ CAPÍTULO I: Organización de la Información <a class="header-anchor" href="#🏛️-capitulo-i-organizacion-de-la-informacion" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Organización de la Información&quot;">​</a></h2><p>Antes de analizar, hay que ordenar. En la ingeniería y en las ciencias sociales, la información no sistematizada se pierde.</p><h3 id="_1-1-tabulacion-de-datos" tabindex="-1">1.1 Tabulación de Datos <a class="header-anchor" href="#_1-1-tabulacion-de-datos" aria-label="Permalink to &quot;1.1 Tabulación de Datos&quot;">​</a></h3><p>Si aplicaste encuestas, debes convertir esas respuestas (&quot;Sí&quot;, &quot;No&quot;, &quot;A veces&quot;) en números y porcentajes. En informática, utilizamos herramientas ofimáticas (Excel, Calc) para crear gráficos de torta o de barras que nos permitan visualizar, por ejemplo, cuántos equipos tienen fallas de software vs fallas de hardware.</p><h3 id="_1-2-analisis-cuantitativo-vs-cualitativo" tabindex="-1">1.2 Análisis Cuantitativo vs Cualitativo <a class="header-anchor" href="#_1-2-analisis-cuantitativo-vs-cualitativo" aria-label="Permalink to &quot;1.2 Análisis Cuantitativo vs Cualitativo&quot;">​</a></h3><ul><li><strong>Cuantitativo:</strong> Lo que puedes contar (Ej: &quot;El 75% de las PC de la escuela carecen de memoria RAM&quot;).</li><li><strong>Cualitativo:</strong> Lo que interpretas de las entrevistas (Ej: &quot;La directora expresa gran frustración porque los niños no pueden ver clases de informática&quot;).</li></ul><h3 id="_1-3-el-analisis-de-involucrados" tabindex="-1">1.3 El Análisis de Involucrados <a class="header-anchor" href="#_1-3-el-analisis-de-involucrados" aria-label="Permalink to &quot;1.3 El Análisis de Involucrados&quot;">​</a></h3><p>Ningún proyecto tecnológico existe en el vacío. Toda intervención afecta a personas. En el análisis de involucrados, identificas a:</p><ol><li><strong>Los Beneficiarios Directos:</strong> Quienes usarán directamente tu solución (ej. La secretaria del ambulatorio, los estudiantes).</li><li><strong>Los Beneficiarios Indirectos:</strong> Quienes mejoran su calidad de vida gracias a tu proyecto (ej. Los pacientes que ahora son atendidos más rápido).</li><li><strong>Los Opositores (Eventuales):</strong> Personas que podrían presentar resistencia al cambio tecnológico (ej. Un empleado que no quiere aprender a usar el nuevo sistema).</li></ol><hr><h2 id="🧩-capitulo-ii-el-contraste-tecnico-social" tabindex="-1">🧩 CAPÍTULO II: El Contraste Técnico-Social <a class="header-anchor" href="#🧩-capitulo-ii-el-contraste-tecnico-social" aria-label="Permalink to &quot;🧩 CAPÍTULO II: El Contraste Técnico-Social&quot;">​</a></h2><p>Aquí es donde tu rol como estudiante del PNFI brilla. Debes tomar la necesidad sentida por la comunidad y traducirla a una necesidad técnica real.</p><p><em>Analogía:</em> Si a un paciente le duele la cabeza (necesidad sentida), él podría pedir una pastilla para el dolor. Pero el médico, tras hacer el diagnóstico, determina que el dolor es por presión arterial alta y le receta un antihipertensivo (solución técnica real).</p><p>En la comunidad, el consejo comunal puede pedirte &quot;Queremos que nos hagas una página web para vender nuestras hortalizas&quot;. Pero tu diagnóstico revela que no tienen conexión a internet, los equipos son del año 2005 y no saben usar Excel. Tu contraste técnico-social te dictará que la verdadera solución para el Trayecto I es el <strong>Soporte Técnico de sus equipos y Alfabetización Tecnológica</strong> en ofimática básica, preparándolos para la página web en el futuro.</p><hr><h2 id="🏗️-capitulo-iii-la-socializacion-devolver-los-resultados" tabindex="-1">🏗️ CAPÍTULO III: La Socialización (Devolver los Resultados) <a class="header-anchor" href="#🏗️-capitulo-iii-la-socializacion-devolver-los-resultados" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: La Socialización (Devolver los Resultados)&quot;">​</a></h2><p>El diagnóstico participativo no es un secreto de la universidad; <strong>le pertenece a la comunidad</strong>. El Reglamento del PSI/T exige la vinculación territorial y el consenso.</p><h3 id="_3-1-la-reunion-de-socializacion" tabindex="-1">3.1 La Reunión de Socialización <a class="header-anchor" href="#_3-1-la-reunion-de-socializacion" aria-label="Permalink to &quot;3.1 La Reunión de Socialización&quot;">​</a></h3><p>Una vez que has analizado los datos y has descubierto cuáles son los problemas reales (técnicos y sociales), debes regresar a la comunidad, convocar a una asamblea o reunión con los líderes y <strong>Socializar los resultados</strong>.</p><ul><li><strong>¿Qué se hace?</strong> Se presentan los gráficos de forma amigable (sin usar lenguaje informático excesivamente complejo), se exponen los problemas encontrados y se <strong>propone</strong> la solución técnica.</li><li><strong>¿Por qué se hace?</strong> Porque la comunidad debe <strong>Validar</strong> tu análisis. Ellos deben decir: &quot;Sí, estamos de acuerdo, ese es nuestro mayor problema y aceptamos que ustedes trabajen en eso&quot;.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Consenso y Validación</strong> Nunca impongas un proyecto tecnológico. Si la comunidad no entiende o no acepta la solución propuesta durante la socialización, el proyecto fracasará en su etapa de ejecución porque no habrá apoyo local. Todo proyecto sociotecnológico requiere la firma de actas de validación por parte de los voceros comunitarios.</p></div><p>Una vez que la comunidad te da el &quot;visto bueno&quot; sobre el problema, pasamos a la fase de diseño de la solución, y para eso utilizaremos la herramienta más poderosa de la planificación de proyectos: <strong>El Enfoque del Marco Lógico</strong>.</p>',30)])])}const h=e(s,[["render",t]]);export{m as __pageData,h as default};
